begin;
select plan(42);
select is(league_week('2026-03-29T23:59:59Z'),'2026-03-23'::date,'DST Sunday remains in UTC week');
select is(league_week('2026-03-30T00:00:00Z'),'2026-03-30'::date,'UTC Monday opens a new week');
select is(league_week('2026-10-25T23:59:59Z'),'2026-10-19'::date,'Autumn DST does not shift the boundary');
create temp table league_fixture as select i,gen_random_uuid() id from generate_series(1,4400) i;
insert into auth.users(id) select id from league_fixture;
insert into league_accounts(user_id,tier) select id,((i-1)/600)::smallint from league_fixture where i<=4200;
-- 4,200 active users in seven tiers; 200 inactive accounts stay out.
select credit_league(id,100+(i%30),'2020-01-06T12:00:00Z') from league_fixture where i<=4200;
select is((select count(*)::integer from league_members m join league_fixture f on f.id=m.user_id),4200,'Thousands of active accounts admitted');
select is((select count(distinct cohort_id)::integer from league_members m join league_fixture f on f.id=m.user_id),140,'140 groups of thirty');
select ok(not exists(select 1 from league_members m join league_fixture f on f.id=m.user_id where f.i>4200),'Inactive users never assigned');
select ok(not exists(select 1 from league_members m join league_fixture f on f.id=m.user_id group by cohort_id having count(*)>30),'Group size bounded');
select credit_league((select id from league_fixture where i=4400),0,'2020-01-06T12:00:00Z');
select is((select count(*)::integer from league_members m join league_fixture f on f.id=m.user_id where f.i=4400),0,'Zero XP never admits');
select is((close_league_weeks('2020-01-12T23:59:59Z',100)->>'closed')::integer,0,'Sunday cannot finalize this week');
-- A delayed job must not let a returning learner enter at the previous tier.
select credit_league((select id from league_fixture where i=29),10,'2020-01-13T00:00:00Z');
select is((select c.tier::integer from league_members m join league_cohorts c on c.id=m.cohort_id where m.user_id=(select id from league_fixture where i=29) and m.week_start='2020-01-13'),1,'Admission first closes the previous cohort and applies promotion');
select is((close_league_weeks('2020-01-13T00:00:00Z',100)->>'closed')::integer,100,'Scheduled batches are bounded');
select is((close_league_weeks('2020-01-13T00:00:00Z',100)->>'closed')::integer,39,'A following batch catches up');
select is((close_league_weeks('2020-01-13T00:00:00Z',100)->>'closed')::integer,0,'Closure retries are idempotent');
select ok(not exists(select 1 from league_members m join league_fixture f on f.id=m.user_id where week_start='2020-01-06' and final_rank is null),'Every old participant has a result');
select is((select count(*)::integer from league_members m join league_fixture f on f.id=m.user_id where week_start='2020-01-06' and outcome='promoted'),600,'Five promoted in every non-top group');
select is((select count(*)::integer from league_members m join league_fixture f on f.id=m.user_id where week_start='2020-01-06' and outcome='relegated'),600,'Five relegated in every non-bottom group');
select ok(not exists(select 1 from league_members m join league_fixture f on f.id=m.user_id join league_cohorts c on c.id=m.cohort_id where (c.tier=0 and m.outcome='relegated') or (c.tier=6 and m.outcome='promoted')),'Boundary tiers never overflow');
select ok(not exists(select 1 from league_members m join league_fixture f on f.id=m.user_id where m.week_start='2020-01-06' and next_tier not between 0 and 6),'All next tiers valid');
select credit_league(id,7,'2020-01-13T12:00:00Z') from league_fixture where i<=4200 and i<>29;
select is((select count(*)::integer from league_members m join league_fixture f on f.id=m.user_id where week_start='2020-01-13'),4200,'Second simulated week admits all active users');
select ok(not exists(select 1 from league_members m join league_fixture f on f.id=m.user_id join league_members old on old.user_id=m.user_id and old.week_start='2020-01-06' join league_cohorts c on c.id=m.cohort_id where m.week_start='2020-01-13' and c.tier<>old.next_tier),'Second week always uses correct previous result');
select credit_league((select id from league_fixture where i=29),5,'2020-01-13T13:00:00Z');
select is((select xp from league_members where user_id=(select id from league_fixture where i=29) and week_start='2020-01-13'),15::bigint,'Later credit accumulates in one membership');
select close_league_weeks('2020-01-20T00:00:00Z',500);
select ok(not exists(select 1 from league_members m join league_fixture f on f.id=m.user_id where final_rank is null),'Two full weeks finalize');
-- New two-person cohort and a singleton, in separate tiers.
select credit_league((select id from league_fixture where i=4398),10,'2020-02-03T12:00:00Z');
select credit_league((select id from league_fixture where i=4399),10,'2020-02-03T12:00:01Z');
insert into league_accounts(user_id,tier) select id,6 from league_fixture where i=4400 on conflict(user_id) do update set tier=6;
select credit_league((select id from league_fixture where i=4400),100,'2020-02-03T12:00:00Z');
select close_league_weeks('2020-02-10T00:00:00Z',100);
select is((select outcome from league_members where user_id=(select id from league_fixture where i=4398) and week_start='2020-02-03'),'promoted','Tied earlier entrant wins the single promotion place');
select is((select outcome from league_members where user_id=(select id from league_fixture where i=4399) and week_start='2020-02-03'),'stayed','Small group zones do not overlap; bottom tier cannot relegate');
select is((select outcome from league_members where user_id=(select id from league_fixture where i=4400) and week_start='2020-02-03'),'stayed','Singleton stays');
select throws_ok($$select close_league_weeks(now(),501)$$,'P0001','Invalid league batch','Unbounded work rejected');
select ok(not has_function_privilege('authenticated','public.credit_league(uuid,integer,timestamptz)','execute'),'Client cannot grant league XP');
select ok(not has_function_privilege('authenticated','public.close_league_weeks(timestamptz,integer)','execute'),'Client cannot close arbitrary weeks');
select ok(not has_table_privilege('authenticated','public.league_cohorts','select'),'Raw cohort roster is private');
select ok(not has_table_privilege('anon','public.league_members','select'),'Guest cannot read memberships');
select set_config('request.jwt.claims',jsonb_build_object('sub',(select id from league_fixture where i=4398),'role','authenticated')::text,true);
set local role authenticated;
-- Temp fixture table is deliberately readable only within this rolled-back test.
select is((select count(*)::integer from league_accounts),1,'RLS exposes only own account');
select is((select count(*)::integer from league_members),1,'RLS exposes only own membership');
select is(set_league_result_consent(true),true,'Own result opt-in can be saved');
select throws_ok('update league_members set xp=9999','42501',null,'Client cannot alter score');
select throws_ok('select credit_league(auth.uid(),100,now())','42501',null,'Client cannot call trusted scoring helper');
select ok(not (learner_league()::text like '%user_id%'),'Leaderboard response has no account IDs');
select ack_league_result('2020-02-03');
select is((select seen_at is not null from league_members where week_start='2020-02-03'),true,'Result acknowledgement belongs to own row');
reset role;
select is((select seen_at is null from league_members where user_id=(select id from league_fixture where i=4399) and week_start='2020-02-03'),true,'Acknowledgement cannot mark another learner result');
delete from auth.users where id=(select id from league_fixture where i=4398);
select is((select count(*)::integer from league_members where user_id=(select id from league_fixture where i=4398)),0,'Erasure removes all personal league records');
select is((select count(*)::integer from league_accounts where user_id=(select id from league_fixture where i=4398)),0,'Erasure removes league tier and preference');
select close_league_weeks('2021-03-01T00:00:00Z',500);
select is((select count(*)::integer from league_members m join league_fixture f on f.id=m.user_id),0,'Old social results expire after a rolling year');
select is((select tier::integer from league_accounts where user_id=(select id from league_fixture where i=4400)),6,'Pruning preserves current tier');
select * from finish();
rollback;
